+
+function liveRunLabel(elapsedMs, timeoutMs) {
+    return timeoutMs
+        ? T('⏳ running {elapsed} of {timeout}', {elapsed: liveFormatClock(elapsedMs), timeout: liveFormatClock(timeoutMs)})
