+function liveRouteTaskOutput(payload, content) {
+    const chat = $('#chat');
+    const id = payload.tool_use_id || '';
+    const call = id ? chat.querySelector(`[data-tool-use-id="${CSS.escape(id)}"]:not([data-tool-done])`) : null;
